  const ref = useRef<THREE.Mesh>(null!)

  // useFrame((state, delta) => {
  //   ref.current.rotation.x += 0.04
  //   ref.current.rotation.y += 0.04

  //   // Object.assign(document, { "foreignScene": state.scene })
